package mindtheindustry.rewards.rewards;

import arc.util.io.*;
import mindustry.gen.*;
import mindtheindustry.core.*;
import mindtheindustry.rewards.*;

/**
 * Reward: unlocks a schematic for an INDIVIDUAL player.
 * The schematic is generated by the server and sent to the player via a packet.
 * Other players don't have it — they will have to ask for it.
 *
 * Note: Mindustry schematics are stored locally per player.
 * The server sends the schematic data via SchematicUnlockPacket.
 */
public class SchematicReward extends Reward{

    /**
     * Serialized schematic data (base64 or custom format).
     * The server generates the schematic and serializes it here.
     */
    public final String schematicData;

    /** Name of the schematic (displayed in the player's schematic list). */
    public final String schematicName;

    public SchematicReward(String schematicData, String schematicName, String displayName, String description){
        super("schematic:" + schematicName, RewardType.SCHEMATIC, displayName, description);
        this.schematicData = schematicData;
        this.schematicName = schematicName;
    }

    @Override
    public void apply(MindTheIndustrySession session, Player chooser, Player target){
        // Register the unlock server-side
        session.unlockSchematicForPlayer(chooser, schematicName);

        // Send the schematic to the player's client (so they add it to their collection)
        if(chooser.con != null && !schematicData.isEmpty()){
            mindtheindustry.net.MindTheIndustryPackets.SchematicUnlockPacket packet = new mindtheindustry.net.MindTheIndustryPackets.SchematicUnlockPacket();
            packet.schematicName = schematicName;
            packet.schematicData = schematicData;
            chooser.con.send(packet, true);
        }
    }

    @Override
    public void write(Writes write){
        super.write(write);
        write.str(schematicData);
        write.str(schematicName);
    }

    public static SchematicReward readSpecific(String id, String name, String desc, Reads read){
        String data = read.str();
        String schemName = read.str();
        return new SchematicReward(data, schemName, name, desc);
    }
}
